const BASE='https://copafacil-web.firebaseio.com/events/-ciddy';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parseStats=s=>Object.fromEntries(String(s??'').split('#').filter(x=>x.includes('=')).map(x=>{const[k,v]=x.split('=');return[k,Number(v)||0]}));
const name=v=>String(v??'A definir').trim().toLocaleLowerCase('pt-BR').replace(/(^|\s)\S/g,c=>c.toLocaleUpperCase('pt-BR'));
const initials=n=>name(n).split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const safeURL=u=>{try{const x=new URL(u);return x.protocol==='https:'?esc(x.href):''}catch{return''}};
let db,teams=[],players=[],matches=[],phases=[],rounds=[],view='overview',busy=false,playerPage=1;
let filters={team:'',phase:'',round:'',status:'',query:'',sort:'goals'};
const isFinished=m=>m.st===3||Boolean(m.finished);
const hasScore=m=>Number.isFinite(m.dt?.qt_g1)&&Number.isFinite(m.dt?.qt_g2);
const team=id=>db?.teams?.[id];
function crest(id){const t=team(id);return t?.url?`<img class="crest" src="${safeURL(t.url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="badge-fallback">${esc(initials(t?.name||'?'))}</span>`}
function avatar(p){return p.url?`<img class="avatar" src="${safeURL(p.url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="avatar avatar-fallback">${esc(initials(p.name))}</span>`}
function fmtDate(m,opts={day:'2-digit',month:'short'}){return m.d_i?new Intl.DateTimeFormat('pt-BR',{...opts,timeZone:'America/Sao_Paulo'}).format(new Date(m.d_i)):'Data a definir'}
function fmtTime(m){return m.d_i?new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(new Date(m.d_i)):'Horário a definir'}
function phaseLabel(id){return `Fase ${phases.indexOf(id)+1}`}
function roundLabel(m){const group=rounds.filter(r=>r.fs===m.fs);return m.m_set?`Rodada ${group.findIndex(r=>r.id===m.m_set)+1}`:'Rodada a definir'}
function prepare(data){db=data;teams=Object.entries(db.teams||{}).map(([id,t])=>({id,...t}));players=Object.entries(db.player||{}).map(([id,p])=>({id,...p,stats:parseStats(p.dt)}));matches=Object.entries(db.matchs||{}).map(([id,m])=>({id,...m})).sort((a,b)=>(a.d_i||Infinity)-(b.d_i||Infinity));phases=[...new Set(matches.map(m=>m.fs).filter(Boolean))];rounds=[...new Map(matches.filter(m=>m.m_set).map(m=>[m.m_set,{id:m.m_set,fs:m.fs}])).values()]}
function standings(phase=phases[0]){return teams.map(t=>{const source=t.dt?.[phase];const stats=source?.dt?parseStats(source.dt):null;const ms=matches.filter(m=>m.fs===phase&&isFinished(m)&&hasScore(m)&&(m.team1===t.id||m.team2===t.id));const c={j:0,v:0,e:0,d:0,gp:0,gc:0,pts:0};for(const m of ms){const gf=m.team1===t.id?m.dt.qt_g1:m.dt.qt_g2;const ga=m.team1===t.id?m.dt.qt_g2:m.dt.qt_g1;c.j++;c.gp+=gf;c.gc+=ga;if(gf>ga)c.v++;else if(gf===ga)c.e++;else c.d++}c.pts=c.v*3+c.e;return{...t,j:stats?.[1]??c.j,v:stats?.[2]??c.v,e:stats?.[3]??c.e,d:stats?.[4]??c.d,gp:stats?.[5]??c.gp,gc:stats?.[6]??c.gc,sg:stats?.[7]??(c.gp-c.gc),pts:stats?.[0]??c.pts,percent:stats?.[8]??(c.j?Math.round(c.pts/(c.j*3)*100):0),rank:source?.col,form:ms.slice(-5).map(m=>{const a=m.team1===t.id?m.dt.qt_g1:m.dt.qt_g2,b=m.team1===t.id?m.dt.qt_g2:m.dt.qt_g1;return a>b?'V':a<b?'D':'E'})}}).sort((a,b)=>(a.rank??999)-(b.rank??999)||b.pts-a.pts||b.sg-a.sg||b.gp-a.gp||a.name.localeCompare(b.name))}
function teamButton(id){return `<button class="team-button" data-team="${esc(id)}">${crest(id)}<span>${esc(name(team(id)?.name))}</span></button>`}
function tableHTML(full=false,phase=phases[0]){const rows=standings(phase);return `<div class="table-wrap"><table class="${full?'full-table':''}"><thead><tr><th scope="col">#</th><th class="team-cell" scope="col">Equipe</th><th scope="col">PTS</th><th scope="col" title="Jogos">J</th><th scope="col" title="Vitórias">V</th><th scope="col" title="Empates">E</th><th scope="col" title="Derrotas">D</th>${full?'<th scope="col" title="Gols pró">GP</th><th scope="col" title="Gols contra">GC</th>':''}<th scope="col" title="Saldo de gols">SG</th>${full?'<th scope="col">Aprov.</th>':''}<th scope="col">Últimos</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${i===0?'leader':''}"><td class="position">${t.rank!=null?t.rank+1:i+1}</td><td class="team-cell">${teamButton(t.id)}</td><td class="points">${t.pts}</td><td>${t.j}</td><td>${t.v}</td><td class="muted">${t.e}</td><td class="muted">${t.d}</td>${full?`<td>${t.gp}</td><td>${t.gc}</td>`:''}<td>${t.sg>0?'+':''}${t.sg}</td>${full?`<td>${t.percent}%</td>`:''}<td><div class="form">${t.form.length?t.form.map(f=>`<span title="${f==='V'?'Vitória':f==='D'?'Derrota':'Empate'}" class="${f==='V'?'win':f==='D'?'loss':''}">${f}</span>`).join(''):'<span>–</span>'}</div></td></tr>`).join('')}</tbody></table></div>`}
function statusLabel(m){return isFinished(m)?'Encerrado':m.st?'Status não identificado':'Agendado'}
function scoreHTML(m){return hasScore(m)?`${m.dt.qt_g1}<small>:</small>${m.dt.qt_g2}`:`<small>×</small>`}
function fixture(m){return `<button class="fixture" data-match="${esc(m.id)}"><div class="fixture-meta"><span>${fmtTime(m)}${m.title?' · '+esc(m.title):''}</span><span class="badge ${isFinished(m)?'neutral':''}">${statusLabel(m)}</span></div><div class="fixture-body"><span class="fixture-team">${crest(m.team1)}<span>${esc(name(team(m.team1)?.name))}</span></span><span class="score">${scoreHTML(m)}</span><span class="fixture-team">${crest(m.team2)}<span>${esc(name(team(m.team2)?.name))}</span></span></div></button>`}
function scorerRows(limit=4){const ps=[...players].filter(p=>p.stats[0]>0).sort((a,b)=>b.stats[0]-a.stats[0]||a.name.localeCompare(b.name));return ps.slice(0,limit).map((p,i)=>`<button class="scorer-row" data-player="${esc(p.id)}"><span class="scorer-rank">${1+ps.findIndex(x=>x.stats[0]===p.stats[0])}</span>${avatar(p)}<span class="scorer-name">${esc(name(p.name))}<small>${esc(name(team(p.team)?.name))}</small></span><span class="goal-pill">${p.stats[0]}</span></button>`).join('')||'<div class="empty">Nenhum gol registrado.</div>'}
function overview(){const done=matches.filter(isFinished),goals=done.filter(hasScore).reduce((n,m)=>n+m.dt.qt_g1+m.dt.qt_g2,0);const pending=matches.filter(m=>!isFinished(m)&&m.team1&&m.team2);const next=pending.filter(m=>m.d_i>=Date.now());const upcoming=(next.length?next:pending).slice(0,2);return `<section class="metric-grid"><div class="metric dark"><span class="metric-label">Partidas disputadas</span><span class="metric-mark">↗</span><div class="metric-number">${done.length}<span style="font-size:23px;color:#8591a6"> / ${matches.length}</span></div><div class="metric-foot">${matches.length-done.length} partidas sem resultado final</div></div><div class="metric"><span class="metric-label">Gols na competição</span><span class="metric-mark">◎</span><div class="metric-number">${goals}</div><div class="metric-foot">${done.length?(goals/done.length).toLocaleString('pt-BR',{maximumFractionDigits:1}):'0'} gols por partida</div></div><div class="metric"><span class="metric-label">Equipes na disputa</span><span class="metric-mark">⚑</span><div class="metric-number">${teams.length}</div><div class="metric-foot">${phases.length} fases com partidas cadastradas</div></div><div class="metric"><span class="metric-label">Jogadores inscritos</span><span class="metric-mark">↗</span><div class="metric-number">${players.length}</div><div class="metric-foot">${players.filter(p=>p.stats[0]>0).length} jogadores já marcaram</div></div></section><div class="overview-grid"><section class="panel"><div class="panel-heading"><div><h2>Classificação</h2><p>${phaseLabel(phases[0])} · Todas as equipes</p></div><a class="text-link" href="#standings">Tabela completa ↗</a></div>${tableHTML()}<div class="panel-note">Posições conforme a fonte. <b>V</b> vitória · <b>E</b> empate · <b>D</b> derrota<br>Toque em uma equipe para explorar o elenco e as partidas.</div></section><div class="side-stack"><section class="panel"><div class="panel-heading"><h2>Próximas partidas</h2><span class="round-pill">${upcoming.length?roundLabel(upcoming[0]):'Agenda'}</span></div><div class="fixture-group">${upcoming.length?`<div class="fixture-date">${fmtDate(upcoming[0],{weekday:'long',day:'numeric',month:'long'})}</div>${upcoming.map(fixture).join('')}`:'<div class="empty">Nenhuma partida agendada.</div>'}</div><div class="sidebar-bottom"><a href="#matches" class="text-link">Ver todos os jogos →</a></div></section><section class="panel"><div class="panel-heading"><h2>Artilharia</h2><a href="#players" class="text-link">Ver todos ↗</a></div>${scorerRows()}<div class="panel-note">Gols registrados por jogador. Empates compartilham posição.</div></section></div></div>`}
function options(list,value){return list.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}
function teamOptions(value){return options([['','Todas as equipes'],...teams.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(t=>[t.id,name(t.name)])],value)}
function phaseOptions(value,all=true){return options([...(all?[['','Todas as fases']]:[]),...phases.map(id=>[id,phaseLabel(id)])],value)}
function sectionTitle(title,description,count){return `<div class="section-title"><div><h2>${title}</h2><p>${description}</p></div>${count!==undefined?`<span class="round-pill">${count}</span>`:''}</div>`}
function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function matchView(){const list=matches.filter(m=>(!filters.team||m.team1===filters.team||m.team2===filters.team)&&(!filters.phase||m.fs===filters.phase)&&(!filters.round||m.m_set===filters.round)&&(!filters.status||(filters.status==='finished'?isFinished(m):!isFinished(m))));const groups=Object.groupBy?Object.groupBy(list,m=>fmtDate(m,{year:'numeric',month:'long',day:'numeric',weekday:'long'})):list.reduce((o,m)=>{const k=fmtDate(m,{year:'numeric',month:'long',day:'numeric',weekday:'long'});(o[k]??=[]).push(m);return o},{});return sectionTitle('Agenda & resultados','Horários de Brasília · Toque em uma partida para ver os detalhes.',`${list.length} partidas`)+`<div class="filters"><select aria-label="Filtrar partidas por equipe" data-filter="team">${teamOptions(filters.team)}</select><select aria-label="Filtrar partidas por fase" data-filter="phase">${phaseOptions(filters.phase)}</select><select aria-label="Filtrar partidas por rodada" data-filter="round">${options([['','Todas as rodadas'],...rounds.filter(r=>!filters.phase||r.fs===filters.phase).map(r=>[r.id,`${phaseLabel(r.fs)} · ${roundLabel({m_set:r.id,fs:r.fs})}`])],filters.round)}</select><select aria-label="Filtrar por situação" data-filter="status">${options([['','Todas as situações'],['scheduled','Sem resultado final'],['finished','Encerradas']],filters.status)}</select><button class="button" data-reset>Limpar filtros</button></div>${list.length?Object.entries(groups).map(([date,ms])=>`<section class="match-day"><h3>${esc(date)}</h3><div class="cards-grid">${ms.map(m=>`<div>${fixture(m)}<p class="subtle" style="margin-top:7px">${phaseLabel(m.fs)} · ${roundLabel(m)}</p></div>`).join('')}</div></section>`).join(''):'<div class="panel empty">Nenhuma partida encontrada com esses filtros.</div>'}<p class="subtle">Fases e rodadas numeradas pela ordem de suas primeiras partidas. A fonte não fornece os nomes das fases, o nome do local ou a descrição dos códigos Q1/Q2. Partidas sem equipes definidas continuam visíveis na agenda.</p>`}
function standingsView(){const exists=teams.some(t=>t.dt?.[filters.phase]);return sectionTitle('Classificação completa','Posições e números registrados no Copa Fácil.')+`<div class="filters"><select data-filter="phase" aria-label="Fase da classificação">${phaseOptions(filters.phase,false)}</select></div><section class="panel">${exists?tableHTML(true,filters.phase):'<div class="empty">A fonte ainda não disponibilizou uma classificação para esta fase.</div>'}<div class="panel-note"><b>PTS</b> pontos · <b>J</b> jogos · <b>V</b> vitórias · <b>E</b> empates · <b>D</b> derrotas · <b>GP</b> gols pró · <b>GC</b> gols contra · <b>SG</b> saldo de gols · <b>Aprov.</b> aproveitamento.<br>Os critérios de desempate não são informados; preservamos a posição da fonte.</div></section>`}
function teamsView(){const list=standings().filter(t=>normalize(t.name).includes(normalize(filters.query)));return sectionTitle('As equipes','Elencos, desempenho e todos os confrontos.',`${teams.length} equipes`)+`<div class="filters"><input type="search" aria-label="Buscar equipe" data-filter="query" placeholder="Buscar equipe…" value="${esc(filters.query)}"></div><div class="cards-grid">${list.map(t=>`<button class="team-card" data-team="${esc(t.id)}"><div class="team-card-top">${crest(t.id)}<div><h3>${esc(name(t.name))}</h3><p>${t.rank!=null?t.rank+1+'º lugar · ':''}${phaseLabel(phases[0])}</p></div></div><div class="team-card-stats"><span><b>${t.pts}</b>Pontos</span><span><b>${t.gp}</b>Gols</span><span><b>${players.filter(p=>p.team===t.id).length}</b>Jogadores</span></div></button>`).join('')}</div>${!list.length?'<div class="empty">Nenhuma equipe encontrada.</div>':''}`}
function statValue(p,code){return p.dt!=null?(p.stats[code]||0):'—'}
function playerTable(ps,rank=false){return `<div class="table-wrap"><table class="full-table"><thead><tr>${rank?'<th scope="col">#</th>':''}<th class="team-cell" scope="col">Jogador</th><th class="team-cell" scope="col">Equipe</th><th scope="col" title="Gols">G</th><th scope="col" title="Jogos">J</th><th scope="col" title="Cartões amarelos">C.AM</th></tr></thead><tbody>${ps.map((p,i)=>`<tr>${rank?`<td class="position">${(playerPage-1)*20+i+1}</td>`:''}<td><button class="player-name" data-player="${esc(p.id)}">${avatar(p)}<span>${esc(name(p.name))}${p.SUSP?'<small>Registro de suspensão</small>':''}</span></button></td><td class="team-cell">${teamButton(p.team)}</td><td class="${filters.sort==='goals'?'stat-highlight':''}">${statValue(p,0)}</td><td>${statValue(p,2)}</td><td class="${filters.sort==='cards'?'stat-highlight':''}">${statValue(p,14)}</td></tr>`).join('')}</tbody></table></div>`}
function playerResults(){const ps=players.filter(p=>(!filters.team||p.team===filters.team)&&normalize(p.name).includes(normalize(filters.query))&&(!filters.status||(filters.status==='suspension'?Boolean(p.SUSP):filters.status==='scorers'?p.stats[0]>0:p.stats[14]>0)));const code=filters.sort==='cards'?14:filters.sort==='games'?2:0;ps.sort((a,b)=>filters.sort==='name'?a.name.localeCompare(b.name):Number(b.dt!=null)-Number(a.dt!=null)||(b.stats[code]||0)-(a.stats[code]||0)||a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(ps.length/20));playerPage=Math.min(playerPage,pages);return {ps,pages}}
function playersView(){const{ps,pages}=playerResults();const goalTotal=players.reduce((n,p)=>n+(p.stats[0]||0),0),scoreTotal=matches.filter(m=>isFinished(m)&&hasScore(m)).reduce((n,m)=>n+m.dt.qt_g1+m.dt.qt_g2,0);return sectionTitle('Jogadores & estatísticas','Gols, participações e disciplina de cada jogador.',`${ps.length} jogadores`)+`<div class="filters"><input type="search" data-filter="query" aria-label="Buscar jogador" placeholder="Buscar jogador…" value="${esc(filters.query)}"><select data-filter="team" aria-label="Filtrar jogadores por equipe">${teamOptions(filters.team)}</select><select data-filter="sort" aria-label="Ordenar jogadores">${options([['goals','Mais gols'],['games','Mais jogos'],['cards','Mais cartões amarelos'],['name','Nome A–Z']],filters.sort)}</select><select data-filter="status" aria-label="Filtrar jogadores por estatística">${options([['','Todos os jogadores'],['scorers','Com gols'],['cards','Com cartões amarelos'],['suspension','Com registro de suspensão']],filters.status)}</select></div><section class="panel">${ps.length?playerTable(ps.slice((playerPage-1)*20,playerPage*20),true):'<div class="empty">Nenhum jogador encontrado com esses filtros.</div>'}<div class="pagination"><span>${ps.length?`${(playerPage-1)*20+1}–${Math.min(playerPage*20,ps.length)} de ${ps.length}`:'0 jogadores'}</span><div><button class="button" data-page="prev" ${playerPage===1?'disabled':''}>← Anterior</button><button class="button" data-page="next" ${playerPage===pages?'disabled':''}>Próxima →</button></div></div></section><p class="subtle"><b>G</b> gols · <b>J</b> jogos · <b>C.AM</b> cartões amarelos. “—” indica que o jogador ainda não tem estatísticas na fonte. Empates são exibidos em ordem alfabética.${goalTotal!==scoreTotal?` Há ${goalTotal} gols atribuídos a jogadores e ${scoreTotal} nos placares; a fonte ainda apresenta essa diferença.`:''}</p>`}
function render(){if(!db)return;document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const active=document.activeElement;const input=active?.matches('input[data-filter]')?{key:active.dataset.filter,start:active.selectionStart,end:active.selectionEnd}:null;$('#content').innerHTML=({overview,standings:standingsView,matches:matchView,teams:teamsView,players:playersView}[view]||overview)();if(input){const el=document.querySelector(`input[data-filter="${input.key}"]`);if(el){el.focus({preventScroll:true});if(el.type!=='search')el.setSelectionRange(input.start,input.end);else try{el.setSelectionRange(input.start,input.end)}catch{}}}}
function detailMetrics(items){return `<div class="detail-metrics">${items.map(([value,label])=>`<div><b>${esc(value)}</b>${esc(label)}</div>`).join('')}</div>`}
function showDetail(html){const d=$('#detail');$('#detail-content').innerHTML=html;d.setAttribute('aria-labelledby','detail-title');if(!d.open)d.showModal();d.scrollTop=0;$('#close-detail').focus()}
function openTeam(id){const t=standings().find(t=>t.id===id);if(!t)return;const roster=players.filter(p=>p.team===id).sort((a,b)=>(b.stats[0]||0)-(a.stats[0]||0)||a.name.localeCompare(b.name));const ms=matches.filter(m=>m.team1===id||m.team2===id);showDetail(`<div class="profile-heading">${crest(id)}<div><h2 id="detail-title">${esc(name(t.name))}</h2><p>${t.rank!=null?t.rank+1+'º lugar · ':''}${phaseLabel(phases[0])} · ${roster.length} jogadores</p></div></div>${detailMetrics([[t.pts,'Pontos'],[t.j,'Jogos'],[t.gp,'Gols pró']])}<div class="detail-info"><div><span>Campanha</span>${t.v} vitórias · ${t.e} empates · ${t.d} derrotas</div><div><span>Defesa e saldo</span>${t.gc} gols sofridos · saldo ${t.sg>0?'+':''}${t.sg}</div></div><h3 class="detail-section">Elenco completo</h3>${roster.length?playerTable(roster):'<p class="muted">Elenco não informado.</p>'}<h3 class="detail-section">Partidas da equipe</h3><div class="compact-list">${ms.length?ms.map(m=>`<p class="subtle">${fmtDate(m)} · ${phaseLabel(m.fs)} · ${roundLabel(m)}</p>${fixture(m)}`).join(''):'<p class="muted">Nenhuma partida cadastrada.</p>'}</div>`)}
function openPlayer(id){const p=players.find(p=>p.id===id);if(!p)return;const appearances=p.stats[2]||0,goals=p.stats[0]||0;const perPhase=Object.entries(p.fs||{});showDetail(`<div class="profile-heading">${avatar(p)}<div><h2 id="detail-title">${esc(name(p.name))}</h2><p>${esc(name(team(p.team)?.name))}</p></div></div>${detailMetrics([[statValue(p,0),'Gols'],[statValue(p,2),'Jogos'],[statValue(p,14),'Cartões amarelos']])}<div class="detail-info"><div><span>Média de gols por jogo</span>${appearances?(goals/appearances).toLocaleString('pt-BR',{maximumFractionDigits:2}):'Não disponível'}</div><div><span>Equipe</span>${teamButton(p.team)}</div></div>${p.SUSP?'<div class="source-info" style="background:#fff8e8;margin-top:20px;border-radius:8px">Há um registro de suspensão na fonte. Os dados fornecidos não permitem confirmar a duração ou se a suspensão ainda está em vigor.</div>':''}<h3 class="detail-section">Desempenho por fase</h3>${perPhase.length?`<div class="table-wrap"><table><thead><tr><th>Fase</th><th>Gols</th><th>Jogos</th><th>C.AM</th></tr></thead><tbody>${perPhase.map(([id,v])=>{const s=parseStats(v.dt);return `<tr><td>${phases.includes(id)?phaseLabel(id):'Fase não identificada'}</td><td>${s[0]||0}</td><td>${s[2]||0}</td><td>${s[14]||0}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="muted">Estatísticas por fase ainda não informadas.</p>'}<p class="subtle">As fontes fornecidas não incluem posição em campo, número da camisa ou eventos individuais por partida.</p>`)}
function openMatch(id){const m=matches.find(m=>m.id===id);if(!m)return;const h=standings(m.fs).find(t=>t.id===m.team1),a=standings(m.fs).find(t=>t.id===m.team2);showDetail(`<h2 id="detail-title" style="font-size:20px;margin-bottom:20px">${esc(name(team(m.team1)?.name))} × ${esc(name(team(m.team2)?.name))}</h2><div class="detail-match"><div style="text-align:center;margin-bottom:20px"><span class="badge ${isFinished(m)?'neutral':''}">${statusLabel(m)}</span></div><div class="fixture-body"><span class="fixture-team">${crest(m.team1)}${esc(name(team(m.team1)?.name))}</span><span class="score">${scoreHTML(m)}</span><span class="fixture-team">${crest(m.team2)}${esc(name(team(m.team2)?.name))}</span></div></div><div class="detail-info"><div><span>Data</span>${fmtDate(m,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><div><span>Horário · Brasília</span>${fmtTime(m)}</div><div><span>Etapa</span>${phaseLabel(m.fs)} · ${roundLabel(m)}</div><div><span>Identificação na fonte</span>${esc(m.title||'Não informada')}</div><div><span>Local</span>Nome não informado${m.l?' · código '+esc(m.l):''}</div><div><span>Resultado</span>${isFinished(m)?hasScore(m)?'Placar final registrado':'Placar não informado':'Aguardando encerramento'}</div></div>${h&&a?`<h3 class="detail-section">As equipes nesta fase</h3><div class="table-wrap"><table><thead><tr><th>Equipe</th><th>Pontos</th><th>Jogos</th><th>Gols</th></tr></thead><tbody>${[h,a].map(t=>`<tr><td>${teamButton(t.id)}</td><td>${t.pts}</td><td>${t.j}</td><td>${t.gp}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="subtle">Escalações, autores e minutos dos gols, cartões por partida e arbitragem não estão disponíveis nesses dados.</p>`)}
function switchView(){const next=location.hash.slice(1)||'overview';view=['overview','matches','standings','teams','players'].includes(next)?next:'overview';filters={team:'',phase:view==='standings'?phases[0]||'':'',round:'',status:'',query:'',sort:'goals'};playerPage=1;if($('#detail').open)$('#detail').close();render()}
window.addEventListener('hashchange',switchView);
document.addEventListener('change',e=>{const key=e.target.dataset.filter;if(!key)return;filters[key]=e.target.value;if(key==='phase')filters.round='';playerPage=1;render()});
document.addEventListener('input',e=>{if(e.target.matches('input[data-filter]')){filters[e.target.dataset.filter]=e.target.value;playerPage=1;render()}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.player)openPlayer(el.dataset.player);else if(el.dataset.team)openTeam(el.dataset.team);else if(el.dataset.match)openMatch(el.dataset.match);else if(el.hasAttribute('data-page')){playerPage+=el.dataset.page==='next'?1:-1;render()}else if(el.hasAttribute('data-reset')){filters={...filters,team:'',phase:'',round:'',status:'',query:''};render()}});
$('#close-detail').addEventListener('click',()=>$('#detail').close());
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function showNotice(message){$('#notice').hidden=!message;$('#notice').textContent=message}
async function refresh(){if(busy)return;busy=true;$('#refresh').disabled=true;try{const payload=await Promise.all(['matchs','teams','player'].map(async endpoint=>{const r=await fetch(`${BASE}/${endpoint}.json`,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);const j=await r.json();if(j!==null&&(typeof j!=='object'||Array.isArray(j)))throw Error('Formato inválido');return j||{}}));prepare({matchs:payload[0],teams:payload[1],player:payload[2],fetchedAt:new Date().toISOString()});$('#sync-state').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});showNotice('');render()}catch(e){$('#sync-state').textContent='Sem conexão com a fonte';showNotice(db?'Não foi possível atualizar. Exibindo os dados consultados em '+new Date(db.fetchedAt).toLocaleString('pt-BR')+'. Tentaremos novamente em um minuto.':'Não foi possível carregar os dados. Use o botão de atualizar para tentar novamente.')}finally{busy=false;$('#refresh').disabled=false}}
document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement){const s=document.createElement('span');s.className=e.target.classList.contains('avatar')?'avatar avatar-fallback':'badge-fallback';s.textContent='—';s.setAttribute('aria-hidden','true');e.target.replaceWith(s)}},true);
$('#refresh').addEventListener('click',refresh);
async function init(){try{const r=await fetch('./data.json');if(!r.ok)throw Error();prepare(await r.json());$('#sync-state').textContent='Dados consultados em '+new Date(db.fetchedAt).toLocaleDateString('pt-BR');switchView()}catch{}await refresh();setInterval(()=>{if(document.visibilityState==='visible')refresh()},60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()})}
init();
